insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-332-938c3b80b53d','data-go-kr-15144809','332','consumer_guidance','냉장고를 사용하던 중 하자가 발생하여 1차 유상 수리를 의뢰했으나 한 달도 되지 않아 동일한 하자가 발생했습니다. 제조사는 2차 수리 역시 유상이라고 안내하고 있는데 수리를 받아도 다시 고장난 것이니 무상 수리를 요청할 수 있나요?','{"구분":" 품질_동일 하자의 2차 수리","답변":"무상 수리를 요구하고, 수리가 불가능할 경우 기존 수리비 환급을 요구할 수 있습니다.   「소비자기본법」 시행령 별표1 “일반적 소비자분쟁해결기준”에 따르면 물품등을 유상으로 수리한 경우 그 유상으로 수리한 날부터 2개월 이내에 소비자가 정상적으로 물품 등을 사용하는 과정에서 그 수리한 부분에 종전과 동일한 고장이 재발한 경우에는 무상으로 수리하되, 수리가 불가한 때에는 종전에 받은 수리비를 환급하여야 한다고 규정하고 있습니다.","번호":"332","질문":"냉장고를 사용하던 중 하자가 발생하여 1차 유상 수리를 의뢰했으나 한 달도 되지 않아 동일한 하자가 발생했습니다. 제조사는 2차 수리 역시 유상이라고 안내하고 있는데 수리를 받아도 다시 고장난 것이니 무상 수리를 요청할 수 있나요?","품목명":" 냉장고"}'::jsonb,'938c3b80b53d9b80acfe28230f07a49965a0e8879449655b3697c844595379c6','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-333-c0679d6ce623','data-go-kr-15144809','333','consumer_guidance','냉장고를 사용하던 중 하자가 발생하여 2차례 수리를 받았으나 동일한 하자가 다시 발생했습니다. 제조사는 재수리 해주겠다고 하나 더 이상 해당 제품을 쓰고 싶지 않은데 환급받을 수 있나요?','{"구분":" 품질_3차례 발생한 동일 하자","답변":"제품 교환 또는 구입가 환급을 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」에 따르면 품질보증기간 이내에 동일하자에 대해 2회까지 수리하였으나 하자가 재발하는 경우 또는 여러 부위 하자에 대해 4회까지 수리하였으나 하자가 재발하는 경우는 수리 불가능한 것으로 보아 제품 교환 또는 구입가 환급으로 규정하고 있으므로 구입가 환급을 요구할 수 있습니다.다만 「소비자분쟁해결기준」은 소비자와 사업자 사이에 발생하는 분쟁을 원활하게 해결하기 위한 합의 또는 권고의 기준을 제시한 것으로 강제력을 가지지 못합니다. 사업자 약관이나 규정 등이 존재한다면 사업자 약관 또는 규정을 적용해야 하며 분쟁해결 방법에 관한 별도의 의사표시가 없는 때에는 「소비자분쟁해결기준」을 적용할 수 있습니다.","번호":"333","질문":"냉장고를 사용하던 중 하자가 발생하여 2차례 수리를 받았으나 동일한 하자가 다시 발생했습니다. 제조사는 재수리 해주겠다고 하나 더 이상 해당 제품을 쓰고 싶지 않은데 환급받을 수 있나요?","품목명":" 냉장고"}'::jsonb,'c0679d6ce623b3f670d4ff170d8f7a3082b004ee2b8af7cc29730b0d606e8a12','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-334-1db4b526be79','data-go-kr-15144809','334','consumer_guidance','냉장고를 사용하던 중 1년 내 AS센터를 3차례 방문하였으나 최근 또 고장이 났습니다. 이에 제조사에 다른 제품으로 교환을 요구했으나 제조사는 서로 다른 하자가 발생한 것으로 교환이 어렵다고 하는데 새 제품 교환받을 수 있을까요?','{"구분":" 품질_서로 다른 하자 발생으로 인한 교환","답변":"제품교환은 어려울 수 있으나, 수리를 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」에서는 품질보증기간 이내에 동일하자에 대해 2회까지 수리하였으나 하자가 재발하는 경우 또는 여러 부위 하자에 대해 4회까지 수리하였으나 하자가 재발하는 경우는 수리 불가능한 것으로 보아 제품 교환 또는 구입가 환급하도록 규정하고 있습니다.품질보증기간은 제조자가 품질보증서에 표시한 기간으로 볼 수 있으나, 해당 기간이 「소비자분쟁해결기준」에서 정한 기한보다 짧은 경우에는 「소비자분쟁해결기준」에서 정한 기간을 적용해야 합니다.동일부위가 아닌 여러 부위의 수리는 4회가 기준이나 공산품 관련 「소비자분쟁해결기준」에서 말하는 수리횟수는 AS센터 방문횟수가 아닌 증상 확인 후 수리·교체한 횟수를 기준으로 하는 바, 윈도우 재설치와 같은 단순 OS 세팅은 수리로 보기는 어려워 교환이 아닌 수리를  요구할 수 있습니다.","번호":"334","질문":"냉장고를 사용하던 중 1년 내 AS센터를 3차례 방문하였으나 최근 또 고장이 났습니다. 이에 제조사에 다른 제품으로 교환을 요구했으나 제조사는 서로 다른 하자가 발생한 것으로 교환이 어렵다고 하는데 새 제품 교환받을 수 있을까요?","품목명":" 냉장고"}'::jsonb,'1db4b526be7951c2862a76cf6c6c9321bd3827f8d64b415ca9a76f21c1dd10c8','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-335-b3cd9dc516ae','data-go-kr-15144809','335','consumer_guidance','설치기사가 냉장고를 설치하던 중 냉장고가 엎어져 제품이 파손되었는데, 어떻게 대응해야 하나요?','{"구분":" 품질_설치 도중 제품 파손","답변":"제품 교환을 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」에서는 사업자가 제품설치 중 발생된 피해에 대해 제품교환하도록 규정하고 있습니다.다만 「소비자분쟁해결기준」은 소비자와 사업자 사이에 발생하는 분쟁을 원활하게 해결하기 위한 합의 또는 권고의 기준을 제시한 것으로 소비자분쟁해결기준은 강제력을 가지지 못합니다. 사업자 약관이나 규정 등이 존재한다면 사업자 약관 또는 규정을 적용해야 하며 분쟁해결 방법에 관한 별도의 의사표시가 없는 때에는 「소비자분쟁해결기준」을 적용할 수 있습니다.","번호":"335","질문":"설치기사가 냉장고를 설치하던 중 냉장고가 엎어져 제품이 파손되었는데, 어떻게 대응해야 하나요?","품목명":" 냉장고"}'::jsonb,'b3cd9dc516ae0f215727afbd25b81e8a58e064e600a51c89ddcaada6f0da6b9b','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-336-a17eebdf8732','data-go-kr-15144809','336','consumer_guidance','구입한지 3년 정도 된 냉장고를 사용하던 중 바닥에 떨어뜨려 고장이 나 수리를 의뢰했습니다. 그러나 제조사는 해당 모델은 단종되었고 현재 보유부품이 없어 수리가 불가능하다고 합니다. 어떻게 대응해야 하나요?','{"구분":" 부당행위_부품을 보유하고 있지 않아 수리 불가능","답변":"품질보증기간이내 유상수리에 해당하는 금액 징수 후 교환을 요구할 수 있고, 품질보증기간 이후에는 정액감가상각비를 공제한 금액에 구입가 10% 가산해 환급을 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」에 따르면 냉장고는 품질보증기간 1년, 부품보유기간 9년으로 규정하고 있습니다. 이 때 공산품 관련 「소비자분쟁해결기준」에서는 부품의무보유기간 이내에 수리용 부품을 보유하고 있지 않아 발생한 피해에 대해서는 품질보증기간 이내인 경우 제품을 교환받거나 구입가 환급을 규정하고 있으며, 품질보증기간 이후에는 제품의 정액감가상각비를 공제한 잔여금액에 구입가의 10%를 가산하여 환급하도록 규정하고 있습니다.따라서, 품질보증기간이내 사용자 고의, 과실로 수리가 필요하나 수리부품이 없어 수리가 불가능한 경우 유상수리에 해당하는 금액 징수 후 제품교환을 요구할 수 있습니다.다만 「소비자분쟁해결기준」은 소비자와 사업자 사이에 발생하는 분쟁을 원활하게 해결하기 위한 합의 또는 권고의 기준을 제시한 것으로 「소비자분쟁해결기준」은 강제력을 가지지 못합니다. 사업자 약관이나 규정 등이 존재한다면 사업자 약관 또는 규정을 적용해야 하며 다만 분쟁해결 방법에 관한 별도의 의사표시가 없는 때에는 「소비자분쟁해결기준」을 적용할 수 있습니다.","번호":"336","질문":"구입한지 3년 정도 된 냉장고를 사용하던 중 바닥에 떨어뜨려 고장이 나 수리를 의뢰했습니다. 그러나 제조사는 해당 모델은 단종되었고 현재 보유부품이 없어 수리가 불가능하다고 합니다. 어떻게 대응해야 하나요?","품목명":" 냉장고"}'::jsonb,'a17eebdf87321ec1684e50bbf91018e49b64ca6bd8be3c173a903d066429dcd5','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-401-c15a2e21192d','data-go-kr-15144809','401','consumer_guidance','에어컨을 사용하던 중 하자가 발생하여 1차 유상 수리를 의뢰했으나 한 달도 되지 않아 동일한 하자가 발생했습니다. 제조사는 2차 수리 역시 유상이라고 안내하고 있는데 수리를 받아도 다시 고장난 것이니 무상 수리를 요청할 수 있나요?','{"구분":" 품질_동일 하자의 2차 수리","답변":"무상 수리를 요구하고, 수리가 불가능할 경우 기존 수리비 환급을 요구할 수 있습니다.   「소비자기본법」 시행령 별표1 “일반적 소비자분쟁해결기준”에 따르면 물품등을 유상으로 수리한 경우 그 유상으로 수리한 날부터 2개월 이내에 소비자가 정상적으로 물품 등을 사용하는 과정에서 그 수리한 부분에 종전과 동일한 고장이 재발한 경우에는 무상으로 수리하되, 수리가 불가한 때에는 종전에 받은 수리비를 환급하여야 한다고 규정하고 있습니다.","번호":"401","질문":"에어컨을 사용하던 중 하자가 발생하여 1차 유상 수리를 의뢰했으나 한 달도 되지 않아 동일한 하자가 발생했습니다. 제조사는 2차 수리 역시 유상이라고 안내하고 있는데 수리를 받아도 다시 고장난 것이니 무상 수리를 요청할 수 있나요?","품목명":" 룸에어컨"}'::jsonb,'c15a2e21192d545becb73e99db6c37a70de48c5952e9ced0c86391876e412908','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-402-d7436d029b06','data-go-kr-15144809','402','consumer_guidance','에어컨을 사용하던 중 하자가 발생하여 2차례 수리를 받았으나 동일한 하자가 다시 발생했습니다. 제조사는 재수리 해주겠다고 하나 더 이상 해당 제품을 쓰고 싶지 않은데 환급받을 수 있나요?','{"구분":" 품질_3차례 발생한 동일 하자","답변":"제품 교환 또는 구입가 환급을 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」에 따르면 품질보증기간 이내에 동일하자에 대해 2회까지 수리하였으나 하자가 재발하는 경우 또는 여러 부위 하자에 대해 4회까지 수리하였으나 하자가 재발하는 경우는 수리 불가능한 것으로 보아 제품 교환 또는 구입가 환급으로 규정하고 있으므로 구입가 환급을 요구할 수 있습니다.다만 「소비자분쟁해결기준」은 소비자와 사업자 사이에 발생하는 분쟁을 원활하게 해결하기 위한 합의 또는 권고의 기준을 제시한 것으로 강제력을 가지지 못합니다. 사업자 약관이나 규정 등이 존재한다면 사업자 약관 또는 규정을 적용해야 하며 분쟁해결 방법에 관한 별도의 의사표시가 없는 때에는 「소비자분쟁해결기준」을 적용할 수 있습니다.","번호":"402","질문":"에어컨을 사용하던 중 하자가 발생하여 2차례 수리를 받았으나 동일한 하자가 다시 발생했습니다. 제조사는 재수리 해주겠다고 하나 더 이상 해당 제품을 쓰고 싶지 않은데 환급받을 수 있나요?","품목명":" 룸에어컨"}'::jsonb,'d7436d029b061381d43c85d7be4e77217fdfd87bc48713fdbb2f7518658244de','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-403-241a7345a3bb','data-go-kr-15144809','403','consumer_guidance','에어컨을 사용하던 중 1년 내 AS센터를 3차례 방문하였으나 최근 또 고장이 났습니다. 이에 제조사에 다른 제품으로 교환을 요구했으나 제조사는 서로 다른 하자가 발생한 것으로 교환이 어렵다고 하는데 새 제품 교환받을 수 있을까요?','{"구분":" 품질_서로 다른 하자 발생으로 인한 교환","답변":"제품교환은 어려울 수 있으나, 수리를 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」에서는 품질보증기간 이내에 동일하자에 대해 2회까지 수리하였으나 하자가 재발하는 경우 또는 여러 부위 하자에 대해 4회까지 수리하였으나 하자가 재발하는 경우는 수리 불가능한 것으로 보아 제품 교환 또는 구입가 환급하도록 규정하고 있습니다.품질보증기간은 제조자가 품질보증서에 표시한 기간으로 볼 수 있으나, 해당 기간이 「소비자분쟁해결기준」에서 정한 기한보다 짧은 경우에는 「소비자분쟁해결기준」에서 정한 기간을 적용해야 합니다.동일부위가 아닌 여러 부위의 수리는 4회가 기준이나 공산품 관련 「소비자분쟁해결기준」에서 말하는 수리횟수는 AS센터 방문횟수가 아닌 증상 확인 후 수리·교체한 횟수를 기준으로 하는 바, 윈도우 재설치와 같은 단순 OS 세팅은 수리로 보기는 어려워 교환이 아닌 수리를  요구할 수 있습니다.","번호":"403","질문":"에어컨을 사용하던 중 1년 내 AS센터를 3차례 방문하였으나 최근 또 고장이 났습니다. 이에 제조사에 다른 제품으로 교환을 요구했으나 제조사는 서로 다른 하자가 발생한 것으로 교환이 어렵다고 하는데 새 제품 교환받을 수 있을까요?","품목명":" 룸에어컨"}'::jsonb,'241a7345a3bbeee8aaf1b2dc07e46486ac388eee4e8f56298811b68783f5547d','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-404-e3c2799dc1fc','data-go-kr-15144809','404','consumer_guidance','설치기사가 에어컨을 설치하던 중 에어컨이 엎어져 제품이 파손되었는데, 어떻게 대응해야 하나요?','{"구분":" 품질_설치 도중 제품 파손","답변":"사업자에게 제품교환을 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」은 사업자가 제품설치 중 발생된 피해에 대해 제품교환 해주도록 규정하고 있습니다.다만 「소비자분쟁해결기준」은 소비자와 사업자 사이에 발생하는 분쟁을 원활하게 해결하기 위한 합의 또는 권고의 기준을 제시한 것으로 강제력을 가지지 못합니다. 사업자 약관이나 규정 등이 존재한다면 사업자 약관 또는 규정을 적용해야 하며 분쟁해결 방법에 관한 별도의 의사표시가 없는 때에는 「소비자분쟁해결기준」을 적용할 수 있습니다.","번호":"404","질문":"설치기사가 에어컨을 설치하던 중 에어컨이 엎어져 제품이 파손되었는데, 어떻게 대응해야 하나요?","품목명":" 룸에어컨"}'::jsonb,'e3c2799dc1fcd203b654b939b92c15491deb2c992182a4ef7dff394d9e8b3193','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15144809-row-405-0f7eedf8af33','data-go-kr-15144809','405','consumer_guidance','구입한 지 3년 정도 된 에어컨을 사용하던 중 바닥에 떨어뜨려 고장이 나 수리를 의뢰했습니다. 그러나 제조사는 해당 모델은 단종되었고 현재 보유부품이 없어 수리가 불가능하다고 합니다. 어떻게 대응해야 하나요?','{"구분":" 부당행위_부품을 보유하고 있지 않아 수리 불가능","답변":"품질보증기간이내 유상수리에 해당하는 금액 징수 후 교환을 요구할 수 있고, 품질보증기간 이후에는 정액감가상각비를 공제한 금액에 구입가 10% 가산해 환급을 요구할 수 있습니다.   공산품 관련 「소비자분쟁해결기준」에 따르면 에어컨은 품질보증기간 2년, 부품보유기간 8년으로 규정하고 있습니다.이 때 공산품 관련 「소비자분쟁해결기준」에서는 부품의무보유기간 이내에 수리용 부품을 보유하고 있지 않아 발생한 피해에 대해서는 품질보증기간 이내인 경우 제품을 교환받거나 구입가 환급을 규정하고 있으며, 품질보증기간 이후에는 제품의 정액감가상각비를 공제한 잔여금액에 구입가의 10%를 가산하여 환급하도록 규정하고 있습니다.따라서, 품질보증기간이내 사용자 고의, 과실로 수리가 필요하나 수리부품이 없어 수리가 불가능한 경우 유상수리에 해당하는 금액 징수 후 제품교환을 요구할 수 있습니다.다만 「소비자분쟁해결기준」은 소비자와 사업자 사이에 발생하는 분쟁을 원활하게 해결하기 위한 합의 또는 권고의 기준을 제시한 것으로 강제력을 가지지 못합니다. 사업자 약관이나 규정 등이 존재한다면 사업자 약관 또는 규정을 적용해야 하며 다만 분쟁해결 방법에 관한 별도의 의사표시가 없는 때에는 「소비자분쟁해결기준」을 적용할 수 있습니다.","번호":"405","질문":"구입한 지 3년 정도 된 에어컨을 사용하던 중 바닥에 떨어뜨려 고장이 나 수리를 의뢰했습니다. 그러나 제조사는 해당 모델은 단종되었고 현재 보유부품이 없어 수리가 불가능하다고 합니다. 어떻게 대응해야 하나요?","품목명":" 룸에어컨"}'::jsonb,'0f7eedf8af33f86c0af515bc35f65aaa0852ff33def1ea2d18e46977b27da7f5','be5ad6ab3e2d6becbf6a32fe8f432c7bb2f575af10c017a42ce5e89bbffdf9d8','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15145204-row-39-1d7b606dddfe','data-go-kr-15145204','39','official_faq','피해구제 신청을 할 수 없는 경우도 있나요?','{"구분":"피해구제","답변":"사업자 소재지(주소)나 연락처를 모르거나, 사업자와 연락이 이루어지지 않는 경우, 소비자의 주장을 입증할 수 없는 경우(입증서류를 제출하지 않는 경우 포함), 영리활동과 관련하여 발생한 분쟁이거나, 임금 등 근로자와 고용인 사이의 분쟁, 개인간 거래 등은 한국소비자원 피해구제가 불가합니다. 또한 국가 또는 지방자치단체가 제공한 물품 등으로 인하여 피해를 입은 경우, 소비자분쟁조정위원회에 준하는 분쟁조정기구에 피해구제가 신청되어 있거나 피해구제 절차를 거친 경우, 소송이 진행중인 경우도 피해구제 처리가 불가합니다.","번호":"39","질문":"피해구제 신청을 할 수 없는 경우도 있나요?"}'::jsonb,'1d7b606dddfe96e7ee94f9e7db97d7ece6a126ee8674828fbabdc3a8655327b5','cc37278c70b82c97421d99c62360edf5ea28de3c095595b060155d4355260258','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
insert into banglog_plus.evidence_candidates (id,dataset_id,source_row,document_type,title,payload,content_sha256,file_sha256,review_status,review_note) values ('kca-15145204-row-44-133a5797a9fe','data-go-kr-15145204','44','official_faq','피해구제 신청은 어떻게 하나요?','{"구분":"피해구제","답변":"1372소비자상담센터를 통해 상담 및 피해처리를 진행하였지만 해결되지 않을 경우, 방문, 우편, 인터넷을 통해 피해구제를 신청할 수 있습니다. 한국소비자원 홈페이지(www.kca.go.kr)를 방문한 후 피해구제-피해구제신청 탭에 분야별 신청서를 다운로드하여 작성 후 증빙서류와 함께 접수해 주시면 됩니다.","번호":"44","질문":"피해구제 신청은 어떻게 하나요?"}'::jsonb,'133a5797a9fe62a7864cc49c1dc42d1f966d04824bb730aeac0633e5a0fc67e5','cc37278c70b82c97421d99c62360edf5ea28de3c095595b060155d4355260258','pending','공식 CSV 직접 확보 및 파일·행 해시 기록. 출처 확보는 개별 법률 명제 검증이나 전문가 승인과 다름. 법률·적용 범위 교차검토 전 GPT 검색 제외.') on conflict(id) do nothing;
